#' Numerosità campionaria
#'
#' 
#' @param tuto Se TRUE mostra il pannello con la descrizione metodologica.
#' @param param Tipo di parametro che l'indagine intende stimare. Determina la
#'   formula utilizzata per il calcolo della numerosità.
#' @param replacement Se TRUE applica la formula per popolazione infinita o
#'   con reinserimento (SCR); se FALSE applica il fattore correttivo (1 - f) per
#'   popolazione finita (SSR).
#' @param N Dimensione N della popolazione di riferimento. Usata per il
#'   fattore correttivo (1 - f) nel campionamento senza reinserimento.
#' @param delta Margine di errore massimo ammesso, espresso nella scala del
#'   parametro: per la proporzione 0 &lt; Δ &lt; 1 (es. 0.03 = 3\%), per la
#'   media qualsiasi valore positivo nella scala della variabile (es. ±2 punti).
#' @param confidence Livello di confidenza in percentuale (default 95).
#' @param prop_P Valore di P utilizzato nella formula. Se non si dispone di
#'   una stima pilota, lasciare 0.5 (varianza massima, stima n per eccesso).
#' @param mean_sigma Scarto quadratico medio σ della variabile di interesse
#'   nella popolazione (richiesto per il caso "media").
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$inputs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$result} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$inputs$asDF}
#'
#' \code{as.data.frame(results$inputs)}
#'
#' @export
samplesize <- function(
    tuto = TRUE,
    param = "proportion",
    replacement = FALSE,
    N = 1000,
    delta = 0.03,
    confidence = 95,
    prop_P = 0.5,
    mean_sigma = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("samplesize requires jmvcore to be installed (restart may be required)")


    options <- samplesizeOptions$new(
        tuto = tuto,
        param = param,
        replacement = replacement,
        N = N,
        delta = delta,
        confidence = confidence,
        prop_P = prop_P,
        mean_sigma = mean_sigma)

    analysis <- samplesizeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

